// Original Classic 910xx molded panels. Grid fit follows the P1/P2 guides;
// detailed plate, perforation and peg dimensions are photo estimates.
export const CLASSIC_PANELS=[["91010","triangle","mini","Black","#292c2b"],["91011","triangle","mini","Blue","#27769d"],["91012","triangle","mini","Red","#d83434"],["91013","triangle","mini","Orange","#f1852a"],["91014","triangle","mini","Silver","#a6ada9"],["91016","triangle","mini","Green","#279469"],["91018","triangle","mini","Fluorescent blue","#305bd6"],["91020","triangle","small","Black","#292c2b"],["91021","triangle","small","Blue","#27769d"],["91022","triangle","small","Red","#d83434"],["91023","triangle","small","Orange","#f1852a"],["91024","triangle","small","Silver","#a6ada9"],["91025","triangle","small","Yellow","#edc93b"],["91028","triangle","small","Fluorescent blue","#305bd6"],["91030","triangle","medium","Black","#292c2b"],["91031","triangle","medium","Blue","#27769d"],["91032","triangle","medium","Red","#d83434"],["91035","triangle","medium","Yellow","#edc93b"],["91040","triangle","large","Black","#292c2b"],["91041","triangle","large","Blue","#27769d"],["91043","triangle","large","Orange","#f1852a"],["91044","triangle","large","Silver","#a6ada9"],["91060","square","mini","Black","#292c2b"],["91064","square","mini","Silver","#a6ada9"],["91068","square","mini","Fluorescent blue","#305bd6"],["91070","square","small","Black","#292c2b"],["91072","square","small","Red","#d83434"],["91074","square","small","Silver","#a6ada9"],["91076","square","small","Green","#279469"],["91078","square","small","Fluorescent blue","#305bd6"],["91080","square","medium","Black","#292c2b"],["91089","square","medium","Brown","#86633e"],["91090","square","large","Black","#292c2b"],["91091","square","large","Blue","#27769d"],["91093","square","large","Orange","#f1852a"]].map(([partNumber,panelShape,panelSize,colorName,color])=>{const tier=['mini','small','medium','large'].indexOf(panelSize),pitch=37.5*Math.SQRT2**(tier+1),reach=37.5*Math.SQRT2**tier;return{id:'panel-'+partNumber,name:`${colorName} ${panelSize} ${panelShape} panel`,partNumber,panel:true,panelShape,panelSize,tier,pitch,reach,color,group:'panels',noBore:true,noSide:true,slots:[],thickness:6.3,bodyDims:panelShape==='square'?[pitch,pitch,6.3]:[2*reach,reach,6.3],reference:`https://shop.knexusergroup.org.uk/products/${partNumber}`,geometryStatus:'Photo reconstruction; peg and perforation dimensions approximate'};});
export function panelPorts(d){const socket=10.1;if(d.panelShape==='square'){const a=d.pitch/2-socket/Math.SQRT2;return[[-1,-1],[1,-1],[1,1],[-1,1]].map(([x,y],i)=>({key:'end'+i,kind:'end',pos:[x*a,y*a,0],dir:[x/Math.SQRT2,y/Math.SQRT2,0]}));}return[[-1,0],[1,0],[0,1]].map(([x,y],i)=>({key:'end'+i,kind:'end',pos:[x*(d.reach-socket),y*(d.reach-socket)-d.reach/3,0],dir:[x,y,0]}));}
export function panelOutline(d){if(d.panelShape==='square'){const h=d.pitch/2-5.5,c=14;return[[-h,-h+c],[-h+c,-h],[h-c,-h],[h,-h+c],[h,h-c],[h-c,h],[-h+c,h],[-h,h-c]];}const a=d.reach;return[[-a+14,-3],[a-14,-3],[a-11,12],[11,a-11],[0,a-16],[-11,a-11],[-a+11,12]].map(([x,y])=>[x,y-a/3]);}
export function panelHoles(d){const out=[];if(d.panelShape==='square'){const rows=[[1],[1,2,3,2,1],[3,4,5,4,5,4,3],[5,6,7,6,7,6,7,6,7,6,5]][d.tier];rows.forEach((n,j)=>{for(let i=0;i<n;i++)out.push([(i-(n-1)/2)*18.75,(j-(rows.length-1)/2)*9.375]);});}else{const rows=[[],[3],[7,5,3],[11,9,7,5,3]][d.tier],dy=16;rows.forEach((n,j)=>{for(let i=0;i<n;i++)out.push([(i-(n-1)/2)*(d.tier>1?15:18.75),12+j*dy-d.reach/3]);});}return out;}
